// PROCESS JOB
// Parse webhook, match profile, dedup
// Profiles fetched from dashboard API (single source of truth)
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

// ── Fetch profile map from dashboard API (Contabo primary, Vercel fallback) ──
const DASHBOARD_URLS = [
  'http://157.173.110.62/api/profiles/mapping',
  'https://sales-dashboard-snowy-beta.vercel.app/api/profiles/mapping',
];
let PROFILES = {};
let fetchError = '';
for (const url of DASHBOARD_URLS) {
  try {
    const response = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    if (response && Object.keys(response).length > 0) { PROFILES = response; break; }
  } catch (err) {
    fetchError = err.message;
  }
}
if (!PROFILES || Object.keys(PROFILES).length === 0) {
  return [{ json: { _result: 'rejected', _reason: 'Failed to fetch profile mapping from all sources: ' + fetchError } }];
}

// ── Build webhook path to profile name mapping dynamically from API ──
const PATH_TO_PROFILE = {};
for (const profileName of Object.keys(PROFILES)) {
  const webhookPath = profileName.toLowerCase() + '-profile-webhook';
  PATH_TO_PROFILE[webhookPath] = profileName;
}

const DEFAULT_LIST = '901815302064';

// ── Get webhook data ──
const webhookData = $input.first().json;
const body = webhookData.body || webhookData;
const headers = webhookData.headers || {};

// ── Extract profile name from webhook path ──
const webhookPath = headers.path || '';
let filterName = '';

for (const [path, profileName] of Object.entries(PATH_TO_PROFILE)) {
  if (webhookPath.includes(path)) {
    filterName = profileName;
    break;
  }
}

if (!filterName) {
  filterName = body.filter_name || body.filterName || body.filter?.name || body.filter_tag || body.filter || '';
}

const projects = body.projects || [body];
const results = [];

for (const p of projects) {
  const client = p.client_details || p.client || {};

  let jobUrl = p.url || p.job_url || p.link || '';
  const urlParam = jobUrl.match(/[?&]url=([^&]+)/);
  if (urlParam) {
    try { jobUrl = decodeURIComponent(decodeURIComponent(urlParam[1])); } catch(e) {
      try { jobUrl = decodeURIComponent(urlParam[1]); } catch(e2) {}
    }
  }

  const idMatch = jobUrl.match(/~(\w+)/);
  const jobId = p.id || p.job_id || p.uid || (idMatch ? idMatch[1] : '');
  if (!jobId) continue;

  const skills = Array.isArray(p.skills)
    ? p.skills
    : (typeof p.skills === 'string' ? p.skills.split(',').map(s => s.trim()).filter(Boolean) : []);

  const job = {
    id: jobId,
    title: p.title || p.job_title || '',
    description: p.description || p.snippet || p.body || p.job_description || '',
    url: jobUrl,
    budget: p.budget || p.fixed_price || p.hourly_budget || '',
    budgetType: p.job_type || p.type || p.budget_type || '',
    skills: skills,
    duration: p.duration || '',
    postedDate: p.published || p.published_at || p.created_at || p.posted_at || new Date().toISOString(),
    clientCountry: client.country?.name || client.country || p.client_country || '',
    clientRating: client.rating || p.client_rating || '',
    clientSpent: client.total_spent || p.client_total_spent || '',
    clientHires: client.total_hires || p.client_hires || '',
    paymentVerified: client.payment_method_verified ?? p.payment_verified ?? false,
    applicants: p.applicants || p.proposals_count || 0
  };

  const profile = PROFILES[filterName];

  if (!profile) {
    results.push({ json: { _result: 'no_profile', _reason: 'No profile matches filter: ' + filterName, job, filterName } });
    continue;
  }

  results.push({ json: {
    _result: 'proceed',
    job,
    filterName,
    profile_id: profile.profile_id || filterName,
    profile_name: filterName,
    stack: profile.stack || '',
    assigned_agent: profile.assigned_agent || '',
    agent_clickup_id: profile.agent_clickup_id || '',
    clickup_list_id: profile.clickup_list_id || DEFAULT_LIST,
    custom_gpt_instructions: ''
  }});
}

if (results.length === 0) {
  return [{ json: { _result: 'rejected', _reason: 'No valid projects in payload' } }];
}

return results;

