// FORMAT DASHBOARD EVENT
// Normalize data from all pipeline paths
// On success path: input = ClickUp API response,
//   pipeline data pulled from Format ClickUp Task via $()
// On other paths: input = pipeline data directly
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
const input = $input.item.json;

let item;
let clickupTaskId = null;
let clickupTaskUrl = null;

try {
  // Success path: pull full pipeline data from Format ClickUp Task
  item = $('Format ClickUp Task').item.json;
  // Input on this path is the ClickUp API response
  clickupTaskId = input.id || null;
  clickupTaskUrl = input.url || null;
} catch(e) {
  // Non-success path: input IS the pipeline data
  item = input;
}

const job = item.job || {};

// Determine outcome
let outcome = item._result || 'unknown';
if (clickupTaskId) outcome = 'proposal_created';
else if (item.taskName && item.proposal) outcome = 'proposal_created';
else if (item.error_detail) outcome = 'gpt_error';

return [{ json: {
  event: 'job_processed',
  timestamp: new Date().toISOString(),
  outcome,
  reason: item._reason || item._errorDetail || item.error_detail || '',

  job: {
    id: job.id || item.job_id || '',
    title: job.title || item.job_title || '',
    url: job.url || item.job_url || '',
    budget: job.budget || '',
    budgetType: job.budgetType || '',
    skills: Array.isArray(job.skills) ? job.skills : [],
    duration: job.duration || '',
    postedDate: job.postedDate || '',
    applicants: job.applicants || 0,
    description: (job.description || '').substring(0, 500),
  },

  client: {
    country: job.clientCountry || '',
    rating: job.clientRating || '',
    spent: job.clientSpent || '',
    hires: job.clientHires || '',
    paymentVerified: job.paymentVerified || false,
  },

  routing: {
    filterName: item.filterName || item.profile_name || item.profile_id || '',
    profileName: item.profile_name || '',
    assignedAgent: item.assigned_agent || '',
    agentClickupId: item.agent_clickup_id || '',
  },

  scores: {
    heuristic: item.heuristicScore ?? null,
    heuristicFlags: item.heuristicFlags || [],
    aiScore: item.aiEval?.score ?? null,
    aiRelevant: item.aiEval?.relevant ?? null,
    aiReason: item.aiEval?.reason || '',
    aiHighlights: item.aiEval?.highlights || [],
    aiRedFlags: item.aiEval?.redFlags || [],
  },

  proposal: item.proposal || null,
  clickupTaskName: item.taskName || null,

  clickup: {
    taskId: clickupTaskId,
    taskUrl: clickupTaskUrl,
  },
} }];

