// Update static data to mark as gpt_failed (allows retry)
const staticData = $getWorkflowStaticData('global');
if (staticData.seenJobs && job.id) {
  staticData.seenJobs[job.id] = { status: 'gpt_failed', timestamp: Date.now() };
}

return [{ json: {
  job_id: job.id || '',
  job_url: job.url || '',
  job_title: job.title || '',
  profile_id: item.profile_id || '',
  profile_name: item.profile_name || '',
  assigned_agent: item.assigned_agent || '',
  error_detail: item._errorDetail || 'Unknown GPT failure'
} }];

// Check if current time is within active hours (16:10 PM - 2:00 AM PKT, Monday-Friday)
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Karachi' }));
const day = now.getDay();
const hour = now.getHours();
const minute = now.getMinutes();

// Skip on Saturday (6) and Sunday (0)
if (day === 0 || day === 6) {
  return [];
}

// Convert current time to minutes since midnight
const currentMinutes = hour * 60 + minute;

// Start time: 16:10 (970 minutes)
const startMinutes = 16 * 60 + 10;

// End time: 2:00 AM next day (120 minutes)
const endMinutes = 2 * 60;

// Check if within time window (spans midnight)
const isActiveHours = currentMinutes >= startMinutes || currentMinutes < endMinutes;

if (isActiveHours) {
  // Return all input items during active hours
  return $input.all();
} else {
  // Return empty array outside active hours
  return [];
}
